CREATE FUNCTION public.normalize_event_text(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT trim(regexp_replace(lower(coalesce(v,'')),'[^a-z0-9]+',' ','g')) $$;
CREATE FUNCTION public.normalize_event_url(v text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT regexp_replace(split_part(trim(coalesce(v,'')),'#',1),'/$','') $$;
CREATE FUNCTION public.check_event_duplicates(candidate jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF octet_length(candidate::text)>40000 THEN RAISE EXCEPTION 'Input too large'; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'title',e.event->>'title','date',e.event->>'date','city',e.event->>'city','published',e.status='published','reason',CASE WHEN public.normalize_event_text(candidate->>'title')=public.normalize_event_text(e.event->>'title') THEN 'Same title, organizer, date and city' ELSE 'Matching URL or similar event details' END)),'[]'::jsonb) INTO result FROM public.event_records e WHERE e.status IN('published','pending_review','changes_requested') AND (
EXISTS(SELECT 1 FROM unnest(ARRAY[candidate->>'sourceUrl',candidate->>'registrationUrl']) a(url),unnest(ARRAY[e.event->>'sourceUrl',e.event->>'registrationUrl']) b(url) WHERE length(public.normalize_event_url(a.url))>0 AND public.normalize_event_url(a.url)=public.normalize_event_url(b.url))
OR (public.normalize_event_text(candidate->>'organizer')=public.normalize_event_text(e.event->>'organizer') AND candidate->>'date'=e.event->>'date' AND public.normalize_event_text(candidate->>'city')=public.normalize_event_text(e.event->>'city') AND (public.normalize_event_text(candidate->>'title')=public.normalize_event_text(e.event->>'title') OR (length(public.normalize_event_text(candidate->>'title'))>=10 AND position(public.normalize_event_text(candidate->>'title') in public.normalize_event_text(e.event->>'title'))>0)))); RETURN result; END; $$; REVOKE ALL ON FUNCTION public.check_event_duplicates(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.check_event_duplicates(jsonb) TO authenticated;
CREATE FUNCTION public.submit_event(candidate jsonb,contact text,acknowledged boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE matches jsonb; new_id uuid; k text; clean jsonb; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
IF octet_length(candidate::text)>40000 THEN RAISE EXCEPTION 'Input too large'; END IF;
FOREACH k IN ARRAY ARRAY['title','description','organizer','city','campus','venue','date','endDate','timeZone','sourceName','eligibilityDetails','skillsDetails','organizerDescription'] LOOP IF jsonb_typeof(candidate->k) IS DISTINCT FROM 'string' OR length(trim(candidate->>k))=0 OR length(candidate->>k)>10000 THEN RAISE EXCEPTION 'Invalid required field: %',k; END IF; END LOOP;
IF length(candidate->>'title')>160 OR length(candidate->>'organizer')>160 OR length(candidate->>'city')>100 OR contact IS NULL OR contact !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(contact)>255 THEN RAISE EXCEPTION 'Invalid event or contact email'; END IF;
IF coalesce(candidate->>'category','') NOT IN('Hackathons','Workshops','Meetups','Conferences','Competitions') OR coalesce(candidate->>'format','') NOT IN('Online','Offline','Hybrid') THEN RAISE EXCEPTION 'Invalid category or format'; END IF;
IF (candidate->>'date')::date<current_date OR (candidate->>'endDate')::date<(candidate->>'date')::date THEN RAISE EXCEPTION 'Invalid event dates'; END IF;
IF coalesce(candidate->>'registrationDeadline','')<>'' AND (candidate->>'registrationDeadline')::date>(candidate->>'date')::date THEN RAISE EXCEPTION 'Deadline must precede event'; END IF;
FOREACH k IN ARRAY ARRAY['sourceUrl','registrationUrl'] LOOP IF coalesce(candidate->>k,'')<>'' AND (candidate->>k !~ '^https?://[^[:space:]/]+([/?#][^[:space:]]*)?$' OR length(candidate->>k)>2048) THEN RAISE EXCEPTION 'Invalid URL'; END IF; END LOOP;
FOREACH k IN ARRAY ARRAY['tags','skills','eligibility','schedule'] LOOP IF jsonb_typeof(candidate->k) IS DISTINCT FROM 'array' OR jsonb_array_length(candidate->k)>30 THEN RAISE EXCEPTION 'Invalid list'; END IF; END LOOP;
IF jsonb_typeof(candidate->'isSample') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Sample label required'; END IF;
matches:=public.check_event_duplicates(candidate); IF jsonb_array_length(matches)>0 AND NOT acknowledged THEN RETURN jsonb_build_object('matches',matches,'needsAcknowledgement',true); END IF;
clean:=candidate-ARRAY['contactEmail','submitter_id','reviewer_id','status','reviewStatus','id']; INSERT INTO public.event_records(submitter_id,event,duplicate_matches) VALUES(auth.uid(),clean,matches) RETURNING id INTO new_id; INSERT INTO public.event_contacts(event_id,contact_email) VALUES(new_id,contact); RETURN jsonb_build_object('id',new_id,'matches',matches,'needsAcknowledgement',false); END; $$; REVOKE ALL ON FUNCTION public.submit_event(jsonb,text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_event(jsonb,text,boolean) TO authenticated;
CREATE FUNCTION public.moderate_event(record_id uuid,action text,reason text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item public.event_records; url text; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF action NOT IN('published','changes_requested','rejected','archived') OR length(reason)>2000 OR(action<>'published' AND length(trim(reason))<3) THEN RAISE EXCEPTION 'Review reason required'; END IF;
SELECT * INTO item FROM public.event_records WHERE id=record_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Submission not found'; END IF;
IF action='published' AND(item.event->>'endDate')::date<current_date THEN RAISE EXCEPTION 'Cannot publish expired event'; END IF;
DELETE FROM public.published_event_urls WHERE event_id=record_id;
IF action='published' THEN FOR url IN SELECT DISTINCT public.normalize_event_url(v) FROM unnest(ARRAY[item.event->>'sourceUrl',item.event->>'registrationUrl']) v WHERE length(public.normalize_event_url(v))>0 LOOP INSERT INTO public.published_event_urls(url,event_id) VALUES(url,record_id); END LOOP; END IF;
UPDATE public.event_records SET status=action,review_reason=reason,reviewer_id=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=record_id; INSERT INTO public.event_review_history(event_id,reviewer_id,action,reason) VALUES(record_id,auth.uid(),action,reason); END; $$; REVOKE ALL ON FUNCTION public.moderate_event(uuid,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.moderate_event(uuid,text,text) TO authenticated;